wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The `requires` clause (len(text) <= 100000) holds of every input,
        // so the text is forwarded unchanged.
        let confirmation = response_channel::send(&reply.text);

        // The `ensures` clauses must hold of every output. If the channel did
        // not confirm delivery, or did not identify the session, no conforming
        // output exists, so trap instead of returning a violating value.
        if !confirmation.delivered {
            panic!("SendReply: channel did not confirm delivery");
        }
        if confirmation.session.is_empty() {
            panic!("SendReply: channel returned no session identity");
        }

        confirmation
    }
}

export!(Node);
